function getPersonalKeys(keys) {
  const result = [];
  (Array.isArray(keys) ? keys : [keys]).forEach((key) => {
    (PERSONAL_FIELD_ALIASES[key] || [key]).forEach((alias) => {
      if (!result.includes(alias)) result.push(alias);
    });
  });
  return result;
}

function getPersonalValue(record, keys) {
  return getRecordValue(record, getPersonalKeys(keys));
}

function normalizePersonalBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  const text = String(value || '').trim().toUpperCase();
  if (['TRUE', 'YES', 'Y', '1'].includes(text)) return true;
  if (['FALSE', 'NO', 'N', '0'].includes(text)) return false;
  return null;
}

function formatPersonalDisplayValue(keys, value) {
  const normalizedKeys = getPersonalKeys(keys);
  if (normalizedKeys.includes('IS_EXECUTIVE') || normalizedKeys.includes('ผู้บริหาร')) {
    return normalizePersonalBool(value) === true ? 'คณะผู้บริหาร' : '';
  }
  if (normalizedKeys.some((key) => PERSONAL_CE_DATE_FIELDS.includes(key))) {
    return formatPersonalDateWithEra(value, 'BE');
  }
  if (normalizedKeys.some((key) => PERSONAL_BE_DATE_FIELDS.includes(key))) {
    return formatPersonalDateWithEra(value, 'BE');
  }
  return value;
}

const PERSONAL_CE_DATE_FIELDS = [
  'PERMIT_EXP',
  'RENEWAL_NOTICE_DATE',
  'START_DATE_CE',
  'RESIGN_DATE',
  'END_DATE_CE'
];

const PERSONAL_BE_DATE_FIELDS = [
  'BIRTHDATE_TEXT'
];

function setPersonalText(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = value || '-';
}

function setInputValue(id, value) {
  const input = document.getElementById(id);
  if (input) input.value = value || '';
}

function splitPersonalFullName(fullName, prefix = '') {
  let text = String(fullName || '').trim().replace(/\s+/g, ' ');
  const prefixText = String(prefix || '').trim();
  if (prefixText && text.startsWith(prefixText)) text = text.slice(prefixText.length).trim();
  if (!text) return { firstName: '', lastName: '' };
  const parts = text.split(' ');
  return {
    firstName: parts.shift() || '',
    lastName: parts.join(' ')
  };
}

function parseThaiBirthText(value) {
  const text = String(value || '').trim().replace(/\s+/g, ' ');
  if (!text) return {};

  let match = text.match(/^(\d{1,2})\s+([^\d\s]+)\s+(\d{4})$/);
  if (match) return { day: match[1], month: match[2], year: match[3] };

  match = text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
  if (match) {
    return {
      day: match[1],
      month: normalizeThaiMonthValue(match[2]),
      year: Number(match[3]) < 2400 ? String(Number(match[3]) + 543) : match[3]
    };
  }

  return {};
}

async function loadPersonalRecordFromApi(config, user) {
  if (!config.API_URL) {
    throw new Error('ยังไม่ได้ตั้งค่า Personal API URL หลัง deploy backend/Code.personal.gs');
  }

  const token = typeof Auth !== 'undefined' && Auth && typeof Auth.getToken === 'function'
    ? Auth.getToken()
    : '';
  if (!token) {
    throw new Error('ไม่พบ Session token กรุณาออกจากระบบแล้วเข้าสู่ระบบใหม่');
  }

  const body = new URLSearchParams();
  body.set('action', 'getPersonalProfile');
  body.set('system', 'MIS');
  body.set('token', token);
  body.set('personId', user.personId || '');
  body.set('email', user.email || '');

  const url = new URL(config.API_URL);
  url.searchParams.set('action', 'getPersonalProfile');
  url.searchParams.set('system', 'MIS');

  const response = await fetch(url.toString(), {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
    body: body.toString()
  });
  const result = await parsePersonalApiResponse(response);
  if (!result.ok) throw new Error(result.message || 'โหลดข้อมูลส่วนบุคคลจาก backend แยกไม่สำเร็จ');
  return normalizeRecord(result.record || {});
}

async function updatePersonalRecordWithApi(config, record) {
  const token = typeof Auth !== 'undefined' && Auth && typeof Auth.getToken === 'function'
    ? Auth.getToken()
    : '';
  if (!token) {
    throw new Error('ไม่พบ Session token กรุณาออกจากระบบแล้วเข้าสู่ระบบใหม่');
  }

  const body = new URLSearchParams();
  body.set('action', 'updatePersonalProfile');
  body.set('system', 'MIS');
  body.set('token', token);
  Object.entries(record || {}).forEach(([key, value]) => {
    body.set(key, value == null ? '' : String(value));
  });

  const url = new URL(config.API_URL);
  url.searchParams.set('action', 'updatePersonalProfile');
  url.searchParams.set('system', 'MIS');

  const response = await fetch(url.toString(), {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
    body: body.toString()
  });
  const result = await parsePersonalApiResponse(response);
  if (!result.ok) throw new Error(result.message || 'บันทึกข้อมูลส่วนบุคคลไม่สำเร็จ');
  return normalizeRecord(result.record || record);
}

async function parsePersonalApiResponse(response) {
  const text = await response.text();
  const body = String(text || '').trim();
  const isHtml = /^<!doctype html|^<html[\s>]/i.test(body);
  if (!response.ok || isHtml) {
    throw new Error('เชื่อมต่อ Personal API ไม่สำเร็จ: Apps Script Web App URL ใช้ไม่ได้ หรือยังไม่ได้ deploy backend ชุด MIS ล่าสุด');
  }
  try {
    return JSON.parse(body);
  } catch (err) {
    throw new Error('Personal API ตอบกลับไม่ใช่ JSON กรุณาตรวจสอบ deploy backend ชุด MIS ล่าสุด');
  }
}

function setDataAlert(message, type = 'info') {
  const el = document.getElementById('personal-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

function renderDetailRowsSection(title, rows, record = currentPersonalRecord) {
  const html = (rows || []).map((row) => {
    const visibleItems = (row || []).map(([label, keys]) => {
      const value = formatPersonalDisplayValue(keys, getPersonalValue(record, keys));
      return { label, value };
    }).filter((item) => !shouldHidePersonalValue(item.value));

    if (!visibleItems.length) return '';
    const cols = Math.min(Math.max(visibleItems.length, 1), 4);
    const items = visibleItems.map(({ label, value }) => {
      return `
        <div class="detail-item">
          <span class="detail-label">${escapeHtml(label)}</span>
          <div class="detail-value">${escapeHtml(value)}</div>
        </div>
      `;
    }).join('');
    return `<div class="detail-row detail-row-${cols}">${items}</div>`;
  }).join('');

  return `
    <section class="detail-section">
      <h3>${escapeHtml(title)}</h3>
      <div class="detail-rows">${html}</div>
    </section>
  `;
}

function shouldHidePersonalValue(value) {
  const text = String(value ?? '').trim();
  if (!text || text === '-') return true;
  return ['false', 'FALSE', 'False'].includes(text);
}

function getPersonalArray(record, key) {
  const value = record && record[key];
  return Array.isArray(value) ? value : [];
}

function degreeLevelDisplay(level) {
  const text = String(level || '').trim().toUpperCase();
  if (text === 'BACHELOR') return 'ปริญญาตรี';
  if (text === 'MASTER') return 'ปริญญาโท';
  if (text === 'DOCTORAL') return 'ปริญญาเอก';
  if (text === 'OTHER') return 'อื่นๆ';
  return level || '-';
}

function degreeLevelValue(level) {
  const text = String(level || '').trim().toUpperCase();
  if (text === 'BACHELOR' || text === 'ปริญญาตรี' || text === 'ตรี') return 'BACHELOR';
  if (text === 'MASTER' || text === 'ปริญญาโท' || text === 'โท') return 'MASTER';
  if (text === 'DOCTORAL' || text === 'ปริญญาเอก' || text === 'เอก') return 'DOCTORAL';
  if (text === 'MASTER_OTHER' || text === 'OTHER' || text === 'อื่นๆ' || text === 'อื่น ๆ' || text === 'ปริญญาโทเพิ่มเติม') return 'OTHER';
  return '';
}

function degreeLevelOrder(level) {
  const value = degreeLevelValue(level);
  if (value === 'DOCTORAL') return 3;
  if (value === 'MASTER') return 2;
  if (value === 'BACHELOR') return 1;
  return 0;
}

function getPersonalEducationRows(record) {
  const rows = getPersonalArray(record, 'education');
  if (rows.length) {
    return rows.map((row) => ({
      educationId: row.EDUCATION_ID || '',
      level: degreeLevelDisplay(row.DEGREE_LEVEL),
      degree: row.DEGREE_NAME || '',
      major: row.MAJOR || '',
      institution: row.INSTITUTION_NAME || row.INSTITUTION_OTHER_NAME || row.INSTITUTION_ID || '',
      year: row.GRAD_YEAR_BE || '',
      nursingField: row.NURSING_FIELD_GROUP || '',
      order: Number(row.DEGREE_ORDER || 0)
    })).sort((a, b) => b.order - a.order);
  }

  return [
    {
      level: 'ปริญญาตรี',
      degree: getPersonalValue(record, 'BACHELOR_DEGREE'),
      major: getPersonalValue(record, 'BACHELOR_MAJOR'),
      institution: getPersonalValue(record, 'BACHELOR_DEGREES_INST_ID'),
      year: getPersonalValue(record, 'BACHELOR_DEGREES_YEAR'),
      nursingField: '',
      order: 1
    },
    {
      level: 'ปริญญาโท',
      degree: getPersonalValue(record, 'MASTER_DEGREE'),
      major: getPersonalValue(record, 'MASTER_MAJOR'),
      institution: getPersonalValue(record, 'MASTER_DEGREES_INST_ID'),
      year: getPersonalValue(record, 'MASTER_DEGREES_YEAR'),
      nursingField: '',
      order: 2
    },
    {
      level: 'ปริญญาเอก',
      degree: getPersonalValue(record, 'DOCTORAL_DEGREE'),
      major: getPersonalValue(record, 'DOCTORAL_MAJOR'),
      institution: getPersonalValue(record, 'DOCTORAL_DEGREES_OTHER_ID'),
      year: getPersonalValue(record, 'DOCTORAL_DEGREES_YEAR'),
      nursingField: '',
      order: 3
    }
  ].filter((row) => row.degree || row.major || row.institution || row.year)
    .sort((a, b) => b.order - a.order);
}

function getPersonalSummaryEducation(record) {
  const rows = getPersonalEducationRows(record);
  const row = rows.find((item) => item.degree || item.major || item.institution || item.year);
  if (!row) {
    return {
      highest: getPersonalValue(record, 'HIGHEST_EDUCATION') || '',
      field: getPersonalValue(record, 'NURSING_FIELD') || ''
    };
  }
  const highest = row.level || getPersonalValue(record, 'HIGHEST_EDUCATION') || '';
  const field = row.nursingField || getPersonalValue(record, 'NURSING_FIELD') || row.major || row.degree || '';
  return { highest, field };
}

function renderPersonalEducationTable(record) {
  const rows = getPersonalEducationRows(record);
  if (!rows.length) {
    return '<div class="personal-empty-table">ไม่มีข้อมูลการศึกษา</div>';
  }

  return `
    <div class="research-table-wrap personal-table-wrap">
      <table class="research-table personal-data-table">
        <thead>
          <tr>
            <th>ลำดับ</th>
            <th>ระดับการศึกษา</th>
            <th>วุฒิการศึกษา</th>
            <th>สาขา</th>
            <th>สถาบัน</th>
            <th>ปีจบ</th>
            <th>กลุ่มสาขา</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map((row, index) => `
            <tr>
              <td>${index + 1}</td>
              <td>${escapeHtml(row.level || '-')}</td>
              <td>${escapeHtml(row.degree || '-')}</td>
              <td>${escapeHtml(row.major || '-')}</td>
              <td>${escapeHtml(row.institution || '-')}</td>
              <td>${escapeHtml(row.year || '-')}</td>
              <td>${escapeHtml(row.nursingField || '-')}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

